import org.w3c.dom.Node;

import java.util.Collection;
import java.util.Collections;

public class WebViewDetector extends LayoutDetector {

    public static final Issue ISSUE = Issue.create(
            "WebViewLayout",
            "WebViews in wrap_content parents",
            "WebView performance optimizations may not work correctly if the parent uses " +
            "`wrap_content` rather than `match_parent`, leading to subtle UI bugs.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(WebViewDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList("WebView");
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Node parentNode = element.getParentNode();
        if (!(parentNode instanceof Element)) {
            return;
        }
        Element parent = (Element) parentNode;
        boolean hasWrapContentWidth = VALUE_WRAP_CONTENT.equals(
                parent.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH));
        boolean hasWrapContentHeight = VALUE_WRAP_CONTENT.equals(
                parent.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT));

        if (hasWrapContentWidth || hasWrapContentHeight) {
            context.report(ISSUE, element, context.getLocation(element),
                    "WebView should not be nested in a parent using wrap_content");
        }
    }
}
```

